#!/bin/bash
# Cursor sessionStart hook — generated by scripts/gen-harness-cursor.ts, do not edit.
# Answers with the tea-rags digest of the workspace as additional_context.
# sessionStart is fire-and-forget: a missing digest is covered by the core rule.

INPUT=$(cat)
ROOT=$(printf '%s' "$INPUT" | jq -r '.workspace_roots[0] // .cwd // empty' 2>/dev/null)
ROOT="${ROOT:-$PWD}"
DIGEST=""
if command -v tea-rags >/dev/null 2>&1; then
  DIGEST=$(tea-rags prime "$ROOT" 2>/dev/null)
fi
if [ -z "$DIGEST" ]; then
  echo '{}'
  exit 0
fi
jq -n --arg context "$DIGEST" '{ additional_context: $context }'
exit 0
